<?php require 'config.php';if(empty($_SESSION['admin_id']))go('admin_login.php');$c=['Pending'=>0,'In Progress'=>0,'Resolved'=>0,'Rejected'=>0,'Total'=>0];foreach($pdo->query('SELECT status,COUNT(*) n FROM complaints GROUP BY status') as $r){$c[$r['status']]=$r['n'];$c['Total']+=$r['n'];}$title='Admin Dashboard';require 'partials/top.php';?><section class="glass hero"><span class="eyebrow">ADMIN CONTROL CENTER</span><h1>Complaint Management</h1><p>Review submissions, update progress and help build a better workplace.</p><a class="button" href="admin_complaints.php">Manage Complaints →</a></section><section class="stats"><div class="glass stat"><small>Total Complaints</small><strong><?=$c['Total']?></strong></div><div class="glass stat"><small>Pending</small><strong><?=$c['Pending']?></strong></div><div class="glass stat"><small>In Progress</small><strong><?=$c['In Progress']?></strong></div><div class="glass stat"><small>Resolved</small><strong><?=$c['Resolved']?></strong></div></section><section class="glass panel"><h3>Quick Links</h3><a class="button" href="admin_complaints.php">View / Update Complaints</a></section><?php require 'partials/bottom.php';?>